import json
from collections import deque

input_grid = [
    [7, 7, 7, 3, 3, 7, 3, 7, 7, 7, 7, 7, 7, 7, 7, 7, 3, 7, 7, 7, 7, 7, 7, 7, 3, 7],
    [7, 3, 7, 7, 3, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 3, 3, 3, 7, 7, 3, 3, 3, 7, 7, 3]
]

def connected_component(grid, start_r, start_c):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    q = deque([(start_r, start_c)])
    component = []

    while q:
        r, c = q.popleft()
        if (r,c) in visited:
            continue
        visited.add((r,c))
        component.append((r,c))

        val = grid[r][c]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == val and (nr,nc) not in visited:
                    q.append((nr,nc))
    return component

# Find components and sizes
components = {}
for r in range(2):
    for c in range(26):
        if (r,c) not in components:
            comp = connected_component(input_grid, r, c)
            components[(r,c)] = (input_grid[r][c], len(comp), comp)

print("Component analysis:")
for k, (val, size, _) in sorted(components.items()):
    print(f"({k}): color={val}, size={size}")

